-- Brasa · Redline for Hyprland (Lua configuration, Hyprland 0.56 or later).
-- Key bindings live in binds.lua, generated by brasa-gen from ~/.config/brasa/keys.tsv.

---- Monitors
-- Defaults for the first start and for monitors never seen before. Each monitor's saved layout and
-- refresh rate are applied on top by brasa-monitors (through wlr-randr) at login and on hotplug.
local here = os.getenv("HOME") .. "/.config/hypr/"
hl.monitor({ output = "eDP-1", mode = "preferred", position = "auto", scale = 1.333333 })
hl.monitor({ output = "",      mode = "preferred", position = "auto", scale = "auto" })

---- Environment
hl.env("XCURSOR_THEME", "Future-cyan-cursors")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

---- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("~/.local/bin/brasa-autostart")
end)

---- Look
hl.config({
    general = {
        gaps_in     = 4,
        gaps_out    = 8,
        border_size = 1,
        col = {
            active_border   = { colors = { "rgba(d00000dd)", "rgba(4a0008dd)" }, angle = 45 },
            inactive_border = "rgba(0c1838ff)",
        },
        resize_on_border = true,
        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,
        active_opacity   = 1.0,
        inactive_opacity = 0.96,
        dim_inactive = true,
        dim_strength = 0.06,

        shadow = {
            enabled        = true,
            range          = 6,
            render_power   = 3,
            color          = 0x22ff0000,
            color_inactive = 0x60000000,
        },

        blur = {
            enabled  = true,
            size     = 5,
            passes   = 2,
            noise    = 0.02,
            vibrancy = 0.17,
        },
    },

    animations = { enabled = true },

    dwindle = { preserve_split = true },

    misc = {
        -- Variable refresh rate is set per monitor by brasa-monitors (each monitor's saved choice,
        -- dynamic by default when its EDID declares a VRR range), so the global default stays off.
        vrr = 0,
        force_default_wallpaper = 0,
        disable_hyprland_logo   = true,
        disable_splash_rendering = true,
        background_color = 0x00040f,
    },

    input = {
        kb_layout  = "es,us",
        kb_variant = ",altgr-intl",
        kb_options = "compose:ins",
        repeat_rate  = 33,
        repeat_delay = 500,
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = {
            natural_scroll = true,
            disable_while_typing = true,
        },
        touchdevice = { output = "eDP-1" },
        tablet      = { output = "eDP-1" },
    },
})

---- Animations: quick and smooth, with a small "pop" when opening
hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1},  {0.32, 1} } })
hl.curve("linear",       { type = "bezier", points = { {0, 0},     {1, 1} } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5}, {0.75, 1} } })
hl.curve("quick",        { type = "bezier", points = { {0.15, 0},  {0.1, 1} } })
hl.curve("easy",         { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

hl.animation({ leaf = "global",        enabled = true, speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",     enabled = true, speed = 4.1,  spring = "easy",         style = "popin 87%" })
hl.animation({ leaf = "windowsOut",    enabled = true, speed = 1.49, bezier = "linear",       style = "popin 87%" })
hl.animation({ leaf = "fadeIn",        enabled = true, speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true, speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 4,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 1.5,  bezier = "linear",       style = "fade" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 1.94, bezier = "almostLinear", style = "slide" })

---- Blur behind the bar, notifications and menus
for _, ns in ipairs({ "waybar", "swaync-control-center", "swaync-notification-window", "launcher", "rofi", "nwg-bar", "swayosd" }) do
    hl.layer_rule({ match = { namespace = "^" .. ns .. "$" }, blur = true, ignore_alpha = 0.2 })
end

---- Window rules
hl.window_rule({ name = "suppress-maximize", match = { class = ".*" }, suppress_event = "maximize" })
hl.window_rule({
    name  = "brasa-floating",
    match = { class = "^(pavucontrol|org.pulseaudio.pavucontrol|blueman-manager|nm-connection-editor)$" },
    float = true,
})
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

---- Touchpad gestures: three-finger horizontal swipe switches workspace
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

---- Mouse: Super + drag moves, Super + right button resizes
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

---- Key bindings (dofile so that a reload picks up regenerated bindings)
dofile(here .. "binds.lua")
